let busy=false;document.querySelectorAll('[data-export]').forEach(b=>b.onclick=async()=>{if(busy)return;busy=true;const format=b.dataset.export,buttons=[...document.querySelectorAll('[data-export]')],progress=document.querySelector('#export-progress');buttons.forEach(x=>x.disabled=true);progress.hidden=false;progress.style.cssText='font-size:11px;color:#79915e;margin-top:16px';const list=M.getLayout(),images=[];try{if(!list.length)throw Error('먼저 문제 사진을 추가해 주세요.');await Promise.race([document.fonts.ready,new Promise(r=>setTimeout(r,2500))]);for(let i=0;i<list.length;i++){progress.textContent=(i+1)+' / '+list.length+' 페이지를 만들고 있어요…';await new Promise(r=>setTimeout(r,15));const c=await renderPage(list[i],i,list.length);const data=bytesFromURL(c.toDataURL(format==='pdf'?'image/jpeg':'image/png',.95));images.push({data,width:c.width,height:c.height});c.width=1;c.height=1}progress.textContent='파일을 저장하고 있어요…';await new Promise(r=>setTimeout(r,10));let data,name=M.fileName()+'.'+format,type='application/octet-stream';if(format==='pdf'){data=makePdf(images);type='application/pdf'}else if(format==='docx'){data=makeDocx(images);type='application/vnd.openxmlformats-officedocument.wordprocessingml.document'}else if(format==='hwpx'){data=makeHwpx(images);type='application/hwp+zip'}else if(images.length===1){data=images[0].data;type='image/png'}else{data=zip(images.map((im,i)=>({name:M.fileName()+'_'+String(i+1).padStart(2,'0')+'.png',data:im.data})));name=M.fileName()+'_이미지.zip';type='application/zip'}M.download(data,name,type);progress.textContent='저장했어요. 다운로드 폴더를 확인해 주세요.';M.toast(format.toUpperCase()+' 파일을 저장했어요.')}catch(e){progress.textContent='저장하지 못했어요: '+e.message;M.toast(e.message||'파일을 만들지 못했어요.')}finally{busy=false;buttons.forEach(x=>x.disabled=false)}});
